import java.io.*; import java.net.Socket; public class TestByte { public static void main(String[] args) throws Exception { Socket socket = new Socket("36.50.135.242", 2208); InputStream in = socket.getInputStream(); OutputStream out = socket.getOutputStream(); out.write("B23DCCN351;YWNm1euS".getBytes()); out.flush(); byte[] buffer = new byte[1024]; int read = in.read(buffer); if(read>0){ System.out.println("Read " + read + " bytes."); System.out.print("Values: "); for(int i=0; i<read; i++) System.out.print(buffer[i] + " "); System.out.println(); System.out.println("String: " + new String(buffer, 0, read)); } socket.close(); } }
